WITH filtered_order_items AS (SELECT *, CAST(unit_price AS INT) AS unit_price_int FROM order_items WHERE unit_price BETWEEN 100 AND 370 AND unit_price <= 370), order_items_stats AS (SELECT order_id, ROUND(STDDEV(quantity), 2) AS stddev_quantity, COUNT(DISTINCT quantity) AS unique_orders FROM filtered_order_items GROUP BY order_id) SELECT order_id, stddev_quantity, unique_orders FROM order_items_stats WHERE stddev_quantity > 64 ORDER BY unique_orders
